script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('threat.framework', 'MITRE ATT&CK');
        v.get('_source').put('threat.technique.id', 'T1190, T1046, T1016');
        v.get('_source').put('threat.technique.name', 'Exploit Public-Facing Application, Network Service Scanning, System Network Configuration Discovery');
        v.get('_source').put('threat.technique.reference', 'https://attack.mitre.org/techniques/T1190, https://attack.mitre.org/techniques/T1046, https://attack.mitre.org/techniques/T1016');
        v.get('_source').put('threat.tactic.id', 'TA0001, TA0007');
        v.get('_source').put('threat.tactic.name', 'Initial Access, Discovery');
        v.get('_source').put('threat.tactic.reference', 'https://attack.mitre.org/tactics/TA0001, https://attack.mitre.org/tactics/TA0007');
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'AWS Guardduty for Suspicious Behaviour Alert');
        v.get('_source').put('threat.detection_description', 'To detect any unusual behaviour from an AWS instance such as communicating with a remote host on an unusual server port or instance is generating unusually large amounts of network traffic to a remote host.');
        v.get('_source').put('threat.severity', 'medium');
        v.get('_source').put('threat.triage_score', 40);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
